---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
	output = "",
	mode = "preferred",
	position = "auto",
	scale = "1.32",
})

-- Laptop display: centered directly below the external monitor.
hl.monitor({
	output = "eDP-1",
	mode = "preferred",
	position = "192x1080",
	scale = "1.32",
})

-- Keep the DisplayPort outputs at 200% when they are connected.  The
-- connector number can change between docks/cables, so cover both names.
-- The resolution-aware rule below still handles any other external output.
hl.monitor({ output = "DP-1", scale = 2 })
hl.monitor({ output = "DP-2", scale = 2 })

-- Scale external displays by their native resolution. Both supported external
-- layouts remain 1920x1080 logical pixels, so the laptop stays aligned below.
local function configureExternalMonitor(monitor)
	if not monitor or monitor.name == "eDP-1" then return end

	local scale = 1.32
	if monitor.width == 1920 and monitor.height == 1080 then
		scale = 1
	elseif monitor.width >= 3840 and monitor.height >= 2160 then
		scale = 2
	end

	hl.monitor({
		output = monitor.name,
		mode = "preferred",
		position = "0x0",
		scale = scale,
	})
end

hl.on("monitor.added", configureExternalMonitor)

