---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- Build the workspace layout from window-open events. Application startup is
-- asynchronous, so launching all three and dispatching immediately races the
-- compositor and can produce an accidental top/bottom layout.
local startupLayoutState = "idle"

hl.on("window.open", function(window)
	if startupLayoutState == "waiting-codex" and window.class == "com.rbdd.termcodex" then
		startupLayoutState = "waiting-fastfetch"
		hl.dispatch(hl.dsp.focus({ window = "class:^com.rbdd.termcodex$" }))
		hl.dispatch(hl.dsp.layout("preselect r"))
		hl.exec_cmd(
			"[workspace 1 silent] ghostty --class=com.rbdd.termfastfetch --font-size=8 -e sh -c 'fastfetch; exec $SHELL'"
		)
	elseif startupLayoutState == "waiting-fastfetch" and window.class == "com.rbdd.termfastfetch" then
		startupLayoutState = "waiting-btop"
		hl.dispatch(hl.dsp.focus({ window = "class:^com.rbdd.termfastfetch$" }))
		hl.dispatch(hl.dsp.layout("splitratio exact 0.55"))
		hl.dispatch(hl.dsp.layout("preselect d"))
		hl.exec_cmd(
			"[workspace 1 silent] ghostty --class=com.rbdd.termbtop --font-size=9 --window-width=95 --window-height=48 -e btop"
		)
	elseif startupLayoutState == "waiting-btop" and window.class == "com.rbdd.termbtop" then
		startupLayoutState = "done"
		hl.dispatch(hl.dsp.focus({ window = "class:^com.rbdd.termbtop$" }))
		hl.dispatch(hl.dsp.layout("splitratio exact 1.8"))
		hl.dispatch(hl.dsp.focus({ window = "class:^com.rbdd.termcodex$" }))
	end
end)

hl.on("hyprland.start", function()
	hl.exec_cmd("hyprpaper")
	hl.exec_cmd("/home/rbdd/.local/bin/waybar-layout restore")
	hl.exec_cmd("playerctld daemon")
	hl.exec_cmd("fcitx5 -d --replace")
	-- Start the idle daemon through its persistent user service.
	hl.exec_cmd("systemctl --user start hypridle.service")
	hl.exec_cmd("systemctl --user start hyprpolkitagent")
	hl.exec_cmd("hyprctl setcursor Bibata-Modern-Ice 30")
	-- Launch only Codex here. The window-open handler launches the others after
	-- their parent panes are confirmed mapped.
	startupLayoutState = "waiting-codex"
	hl.exec_cmd("[workspace 1 silent] ghostty --class=com.rbdd.termcodex -e sh -c 'codex resume --last; exec $SHELL'")
end)

